// Set up page and event handling on page load.
suitehelp.onload = function () {
    "use strict";

    // Global variable setup
    suitehelp.currid = $("body").attr("id");

    // Left bar setup
    suitehelp.setupLeftBar();

var hp = suitehelp.getQueryString("hp");
 if(hp){
      if(window.innerWidth < 1024) {
                   $('#leftbar').addClass('active');
                   $('.in').slideDown();
              }
 }
    // Do absolute URL conversion of header, footer, article, to get it ready for ajaxification
    function urlConvert(name) {
        var $name = $(name);

        // Nothing to convert if the element doesn't exist
        if (!$name.length) {
            return;
        }

        $name.html(suitehelp.makeAbsoluteURLs(document.location.href, $name.html()));
    }
    urlConvert("article");
    urlConvert("#header");
    urlConvert("footer");
    urlConvert("#breadcrumbs");


    if (suitehelp.styleArticle !== undefined) {
        suitehelp.styleArticle();
    }

    // Set up History.js. 
    // Must come after any links that are created
    suitehelp.setupHistory();

    suitehelp.setUpAudienceSelector();

    // Set up search form handling
    suitehelp.setupSearch();

    // Enable the #toolbar
    suitehelp.setupToolbar();

    suitehelp.loadCustomCode();

    // Call customization code
    try {
        whLoad(true);
    } catch (ignore) {
    }

    // Add the ajax class to the body as relevant
    suitehelp.checkAjax(
        function () {
            $("body").addClass("ajax");
            var hps = suitehelp.getQueryString("hps");
            if(hps){
            $("#search_textbox").val(hps);
            suitehelp.performSearch(hps);
            suitehelp.openCurrentLeftBarPane("search_pane");  
            suitehelp.scrollToCurrent();
            }
            else{
            if(suitehelp.getQueryString("nav")){
                suitehelp.setExtraHLeftPane();
                suitehelp.openCurrentLeftBarPane("index_pane"); 
            }
            else
                suitehelp.openCurrentLeftBarPane("toc_pane"); 
            }
            suitehelp.setupIndex();
            suitehelp.loadSearch();
            suitehelp.initializeBreadCrumbs();
            suitehelp.defineLeftBarEvents();
            suitehelp.resizeArticlePane();
            suitehelp.resizeLeftPane();
            suitehelp.setHiddenElement();                  
            /*suitehelp.zoomImage(); */
            suitehelp.scrollToCurrent();
            suitehelp.checkScroll();
        },
        function () {
            suitehelp.loadIndex();
            suitehelp.updateSearchUrls();
            // If a q= parameter is available on load, perform an initial search
            suitehelp.performInitialSearch();
            suitehelp.initializeBreadCrumbs();
            suitehelp.openCurrentLeftBarPane(suitehelp.getCurrentPane().attr("id"));
            suitehelp.defineLeftBarEvents();
            suitehelp.resizeArticlePane();
            if( suitehelp.getCurrentPane().attr("id")==="index_pane"||suitehelp.getCurrentPane().attr("id")==="glossary_pane")
            suitehelp.setExtraHLeftPane();
            suitehelp.resizeLeftPane();
            suitehelp.setHiddenElement(); 
            /*suitehelp.zoomImage();   */
            suitehelp.scrollToCurrent();
            suitehelp.checkScroll();
        }
    );
    
    		

    
    suitehelp.checkScroll();
};

